#include <iostream>
using namespace std;
int main() {
    int a, b, x, y;
    cin >> a >> b >> x >> y;
    cout << (a > b) << " " << (x < y) << " " << ((a > b) && (x < y)) << endl;
    cout << (a > b) << " " << (x < y) << " " << ((a > b) || (x < y)) << endl;
    cout << !(a > b) << " " << !(x < y) << endl;
    return 0;
}
